namespace BlazorApp.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly string[] _templates =
    [
        "New comment on your post",
        "Your build succeeded",
        "Deployment to production completed",
        "Pull request #42 was merged",
        "New follower: octocat",
        "Security alert resolved",
        "Disk usage exceeded 80%",
        "Scheduled maintenance tonight at 11 PM",
        "Your subscription renews tomorrow",
        "New release v2.1.0 is available"
    ];

    public Task<List<NotificationItem>> GetInitialNotificationsAsync()
    {
        var notifications = Enumerable.Range(0, 3).Select(_ => CreateNotification()).ToList();
        return Task.FromResult(notifications);
    }

    public Task<NotificationItem?> CheckForNewNotificationAsync()
    {
        // ~30% chance a new notification arrives each poll
        if (Random.Shared.Next(100) < 30)
        {
            return Task.FromResult<NotificationItem?>(CreateNotification());
        }
        return Task.FromResult<NotificationItem?>(null);
    }

    private NotificationItem CreateNotification()
    {
        var id = Interlocked.Increment(ref _nextId);
        return new NotificationItem
        {
            Id = id,
            Message = _templates[Random.Shared.Next(_templates.Length)],
            Timestamp = DateTime.Now
        };
    }
}

@page "/notifications"
@rendermode InteractiveServer
@implements IDisposable
@inject BlazorApp.Services.NotificationService NotificationService

<PageTitle>Notifications</PageTitle>

<h1>Notifications <span class="badge bg-primary">@notifications.Count</span></h1>

@if (RendererInfo.IsInteractive)
{
    <p class="text-muted"><small>🟢 Live — polling for new notifications</small></p>
}
else
{
    <p class="text-muted"><small>⏳ Loading interactive mode…</small></p>
}

@if (notifications.Count == 0)
{
    <p>No notifications yet.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-center">
                @n.Message
                <span class="text-muted" style="font-size: 0.8em;">@n.Timestamp.ToString("HH:mm:ss")</span>
            </li>
        }
    </ul>
}

@code {
    private List<BlazorApp.Services.NotificationItem> notifications = new();
    private CancellationTokenSource? _cts;

    [PersistentState]
    public List<BlazorApp.Services.NotificationItem>? PersistedNotifications { get; set; }

    protected override async Task OnInitializedAsync()
    {
        if (PersistedNotifications is not null)
        {
            // Restored from prerender — skip the fetch
            notifications = PersistedNotifications;
        }
        else
        {
            notifications = await NotificationService.GetInitialNotificationsAsync();
            PersistedNotifications = notifications;
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
                var newItem = await NotificationService.CheckForNewNotificationAsync();
                if (newItem is not null)
                {
                    notifications.Insert(0, newItem);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (TaskCanceledException)
            {
                break;
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

